USERS = [
    {"username": "ivan", "email": "ivan@example.com", "age": 25},
    {"username": "olga", "email": "olga@example.com", "age": 17},
    {"username": "petr", "email": "petr@example.com", "age": 19},
]


def test_serialize_returns_string():
    result = serialize_users(USERS)
    assert isinstance(result, str), "serialize_users должна возвращать строку JSON, а не список"


def test_roundtrip_preserves_data():
    json_text = serialize_users(USERS)
    restored = deserialize_users(json_text)
    assert restored == USERS, "после сериализации и обратного разбора данные должны совпадать с исходными"


def test_count_adults():
    assert count_adults(USERS) == 2, "среди USERS двое старше 18 лет (ivan и petr)"


def test_count_adults_empty():
    assert count_adults([]) == 0, "для пустого списка количество взрослых должно быть 0"
